mapper.select:
SELECT a.id, a.title, a.summary, a.content, a.author_id AS authorId, a.category_id AS categoryId, a.status AS status, a.version AS version, a.view_count AS viewCount, a.submit_time AS submitTime, a.publish_time AS publishTime, a.create_time AS createTime, a.update_time AS updateTime, u.nickname AS authorName, c.name AS categoryName FROM cms_article a LEFT JOIN sys_user u ON a.author_id = u.id AND u.deleted = 0 LEFT JOIN cms_category c ON a.category_id = c.id AND c.deleted = 0 WHERE a.deleted = 0
AND a.title LIKE CONCAT('%', #{query.title}, '%')
AND a.status = #{query.status}
AND a.author_id = #{query.authorId}
AND a.category_id IN
#{cid}
ORDER BY a.create_time DESC
